/**
 * FITX body map artwork: one stylised, gender-neutral athletic figure seen from the front and the back.
 * Pure data (no React, no DOM) so node scripts and tests can import it.
 *
 * Both views share one viewBox. Each view has a body silhouette (the neutral base), the muscle plates of every
 * region drawn on it (left and right side as separate paths; some regions have more than one plate per side)
 * and detail plates that belong to no region (the shins). Plates sit inside the silhouette; the even gaps
 * between them come from a stroke in the base colour (see BodyMap.module.css).
 * Every shape is a smooth closed curve through hand-placed points, drawn for one side and mirrored, so the
 * figure is exactly symmetric; neighbouring plates share their border points. Edit in any SVG editor if needed,
 * keeping each region's left path before its right one (tests/unit/anatomy.test.ts checks this).
 * The figure faces the viewer in the front view, so its right side is on the left of the image.
 */
import type { RegionKey } from "@/lib/training/anatomy";

export type BodyView = "front" | "back";

export type BodyViewArt = {
  /** The whole figure outline, filled with the body base colour. */
  silhouette: string;
  /** Plates per region, drawn in this order; a region missing here is not visible from this side. */
  regions: Partial<Record<RegionKey, readonly string[]>>;
  /** Plates that are part of the drawing but of no region. */
  details: readonly string[];
};

export const BODY_VIEWBOX = { x: 6, y: 8, width: 188, height: 416 } as const;
export const BODY_VIEWBOX_ATTR = `${BODY_VIEWBOX.x} ${BODY_VIEWBOX.y} ${BODY_VIEWBOX.width} ${BODY_VIEWBOX.height}`;

